import {lstat,readFile,writeFile,rename} from 'node:fs/promises';
const p=JSON.parse(process.env.PONDEROSA_PARAMETERS??'{}');
const name='pinecone-runtime-capability.json',s=await lstat(name);
if(!s.isFile()||s.isSymbolicLink()||s.size>8192)throw Error('Invalid runtime qualification evidence');
const q=JSON.parse(await readFile(name,'utf8'));
if(q.schema!==1||q.model!==p.requiredModel||q.effort!==p.requiredEffort)throw Error('Exact requested model and reasoning qualification required; no fallback permitted');
if(q.supported!==true)throw Error('Requested runtime unavailable; no fallback permitted. '+String(q.error??'Model access has not been verified').slice(0,1000));
// In activated installations, use canonical receipts to retain fresh qualification.
// No provider inference, configuration changes or credentials are involved here.
if(p.runtimeBranchId){
 if(q.branchId!==p.runtimeBranchId||!/^[0-9a-f-]{36}$/.test(p.runtimeBranchId))throw Error('Runtime qualification owner mismatch');
 const host=process.env.PONDEROSA_HOST??'127.0.0.1',reachable=['0.0.0.0','::'].includes(host)?'127.0.0.1':host;
 const origin='http://'+reachable+':'+(process.env.PONDEROSA_PORT??'18793');
 async function get(path){const r=await fetch(origin+path,{signal:AbortSignal.timeout(3000)});if(!r.ok)throw Error('Canonical runtime evidence unavailable');return r.json();}
 const bindings=await get('/api/branches/'+p.runtimeBranchId+'/configuration');let observed=[];
 for(const ref of ['scout','reviewer','spokesperson']){
  const id=bindings.agents?.[ref];if(typeof id!=='string'||!/^[0-9a-f-]{36}$/.test(id))throw Error('Installed runtime binding unavailable');
  const d=await get('/api/branches/engine/agents/'+id+'?limit=3');
  if(d.agent?.model!==p.requiredModel||d.agent?.effort!==p.requiredEffort||d.agent?.archived)throw Error('Configured runtime differs from required model/reasoning; no fallback permitted');
  const fresh=(d.runs??[]).filter(r=>r.startedAt>=q.modelConfiguredAt);
  if(fresh.some(r=>r.status==='completed'&&(r.model!==p.requiredModel||r.effort!==p.requiredEffort)))throw Error('Actual provider receipt used an unrequested model/reasoning; no fallback permitted');
  observed.push(...fresh.filter(r=>r.status==='completed'&&r.model===p.requiredModel&&r.effort===p.requiredEffort&&Number.isFinite(Date.parse(r.completedAt))).map(r=>({id:r.id,at:r.completedAt})));
 }
 const newest=observed.sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))[0];
 if(newest&&Date.parse(newest.at)>Date.parse(q.verifiedAt)){
  q.verifiedAt=newest.at;q.provenance='Canonical actual matching provider receipt '+newest.id+' in this installation';
  const temp=name+'.'+process.pid+'.tmp';await writeFile(temp,JSON.stringify(q),{flag:'wx',mode:0o600});await rename(temp,name);
 }
}
if(!Number.isFinite(Date.parse(q.verifiedAt))||Date.now()-Date.parse(q.verifiedAt)>86400000||Date.parse(q.verifiedAt)>Date.now()+60000)throw Error('Fresh qualification of the exact requested model and reasoning required; no fallback permitted');
let input='';for await(const c of process.stdin){input+=c;if(Buffer.byteLength(input)>262144)throw Error('Input too large');}process.stdout.write(input);

steps.instructions:
CURRENT OPERATOR AUTHORIZATION: activate this existing Pinecone for autonomous research and normal updates to the user in this Pinecone's own existing UI. This supersedes historical shadow-only instructions. Research needs no incoming event. Only the bound spokesperson may publish user-facing Communication; Scout and Reviewer never message the user. No emails, other agents' chats, Slack, third parties or new channels are authorized. No synthetic test messages. Use only existing authorized read-only sources; never modify connectors, grant permissions, copy credentials, import unrelated data or export private memory. Do not read denied sessions/paths. Keep records bounded. Scripts own the ledger; do not edit host files. Direct user requests may receive normal replies in this UI; unknown applicability, stale/known/dismissed/resolved facts stay internal. Missing access is a gap, never proof of absence. Reuse the exact-model guard and independent review. The existing workspace brief contains current explicit scope and known facts.
Read pinecone-context.md and coverage ledger. Form up to three grounded questions, choose one by benefit, novelty, coverage and cost, and actually research it even without incoming events. Rotate supported needs, opportunities and exploration. At most four public searches and six narrow context reads. Return at most 6 KiB evidence, dates, known facts, applicability, uncertainties, sources and one next step. Missing access does not prove absence. Use the corrected V3 principle: autonomous research precedes a separate attention decision. Use 60/25/15 needs/opportunities/exploration as an experimental allocation, not a validated optimum.
Focus: {{parameter:focus}}

